            width: 100%; padding: 12px; font-size: 12px; font-weight: 700; border: 1px solid #cbd5e1; outline: none; border-radius: 0; appearance: none; background: #fff;
        }
        .lux-select {
            background: #fff url('data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22292.4%22%20height%3D%22292.4%22%3E%3Cpath%20fill%3D%22%23000000%22%20d%3D%22M287%2069.4a17.6%2017.6%200%200%200-13-5.4H18.4c-5%200-9.3%201.8-12.9%205.4A17.6%2017.6%200%200%200%200%2082.2c0%205%201.8%209.3%205.4%2012.9l128%20127.9c3.6%203.6%207.8%205.4%2012.8%205.4s9.2-1.8%2012.8-5.4L287%2095c3.5-3.5%205.4-7.8%205.4-12.8%0-5-1.9-9.2-5.5-12.8z%22%2F%3E%3C%2Fsvg%3E') no-repeat right 12px center / 10px;
        }
        .obsidian-button {
            background: linear-gradient(135deg, #0f172a 0%, #020617 100%); position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); width: 100%; padding: 20px; color: #fff; font-weight: 900; font-size: 14px; letter-spacing: 4px; text-transform: uppercase; cursor: pointer; transition: all 0.3s; border-radius: 0;
        }
        .obsidian-button:hover { transform: translateY(-2px); box-shadow: 0 15px 30px rgba(0,0,0,0.4); }
