            position: absolute; top: 0; left: -100%; width: 100%; height: 100%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.05), transparent);
            animation: beamSweep 6s infinite;
        }
        @keyframes beamSweep { 0% { left: -100%; } 20% { left: 100%; } 100% { left: 100%; } }
        </style>
    `;

  card.innerHTML =
    window.createConfigHeader("HYGIENE", "🧼", "Docu-Scrub").outerHTML +
    styleBlock +
    `
        <div style="padding:16px; font-family: 'Inter', 'Segoe UI', sans-serif; background: #fff;">
            <div style="margin-bottom: 24px;">
                <p style="font-size: 13px; color: #64748b; margin:0; line-height: 1.5;">Clean Document and Prepare it for Execution</p>
                <div style="background:#fffbeb; border:1px solid #fcd34d; padding:10px 12px; margin-top:12px; font-size:11px; color:#92400e; display:flex; align-items:flex-start; gap:8px;">
                    <span style="flex-shrink:0;">⚠️</span><span>Turn off <b>Track Changes</b> in Word before scrubbing.</span>
                </div>
            </div>

            <!-- Typography Normalization -->
            <div class="label-ceremony" style="color:#1565c0;">✨ Typography Normalization</div>
            <div class="scrub-group" style="background:#f1f8ff; border-color:#bfdbfe; margin-bottom:24px; padding:10px 12px;">
                <div style="display:flex; gap:12px; text-align:center;">
