                        <label style="font-size:9px; font-weight:700; color:#475569; text-transform:uppercase; margin-bottom:2px; display:block;">Font Family</label>
                        <select id="scrubFontName" class="lux-select" style="padding:4px; width:100%; text-align:center; height:28px; font-size:11px;">
                            <option value="Inter">Inter (Premium)</option>
                            <option value="Outfit">Outfit (Clean)</option>
